"package main

import (
	"database/sql"
	"fmt"
	"log"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		log.Fatalf("Failed to open db: %v", err)
	}
	defer db.Close()

	rows, err := db.Query(`
		SELECT id, track_id, track_type, display_name, played_at, duration_seconds, play_status, planned_block_time 
		FROM play_history 
		ORDER BY id DESC 
		LIMIT 40
	`)
	if err != nil {
		log.Fatalf("Failed to query play_history: %v", err)
	}
	defer rows.Close()

	fmt.Printf("%-5s | %-12s | %-12s | %-30s | %-19s | %-5s | %-8s | %-10s\n", 
		"ID", "Track ID", "Type", "Display Name", "Played At", "Dur", "Status", "BlockTime")
	fmt.Println("------------------------------------------------------------------------------------------------------------------------")

	for rows.Next() {
		var id int
		var trackID, trackType, displayName, playedAt, playStatus, plannedBlockTime string
		var durationSeconds int
		err := rows.Scan(&id, &trackID, &trackType, &displayName, &playedAt, &durationSeconds, &playStatus, &plannedBlockTime)
		if err != nil {
			log.Fatalf("Failed to scan row: %v", err)
		}
		fmt.Printf("%-5d | %-12s | %-12s | %-30.30s | %-19s | %-5d | %-8s | %-10s\n", 
			id, trackID, trackType, displayName, playedAt, durationSeconds, playStatus, plannedBlockTime)
	}
}
"

"package main

import (
	"database/sql"
	"fmt"
	"log"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		log.Fatalf("Failed to open db: %v", err)
	}
	defer db.Close()

	rows, err := db.Query(`
		SELECT timestamp, level, message 
		FROM local_logs 
		WHERE timestamp >= '2026-06-15 12:40:00' AND timestamp <= '2026-06-15 12:50:00'
		ORDER BY timestamp ASC
	`)
	if err != nil {
		log.Fatalf("Failed to query local_logs: %v", err)
	}
	defer rows.Close()

	fmt.Printf("%-19s | %-5s | %s\n", "Timestamp", "Level", "Message")
	fmt.Println("------------------------------------------------------------------------------------------------------------------------")

	for rows.Next() {
		var timestamp, level, message string
		err := rows.Scan(&timestamp, &level, &message)
		if err != nil {
			log.Fatalf("Failed to scan row: %v", err)
		}
		fmt.Printf("%-19s | %-5s | %s\n", timestamp, level, message)
	}
}
"

